import React,{useEffect,useState}from'react';import{createRoot}from'react-dom/client';import'./style.css';import OperationsPanel from './OperationsPanel';import RecordEditor from './RecordEditor';import PublicHome from './PublicHome';import PackageImageUpload from './PackageImageUpload';import FinanceServicePanel from './FinanceServicePanel';import EnterpriseSaasPanel from './EnterpriseSaasPanel';import OfflineSyncPanel from './OfflineSyncPanel';
const API_BASE=(import.meta.env.VITE_API_BASE_URL||'').replace(/\/+$/,'');
const assetUrl=(value?:string|null)=>!value?'https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=900&q=80':value.startsWith('/')?API_BASE+value:value;
type Session={accessToken:string,refreshToken?:string,user:{id:string;tenantId?:string;name:string;email:string;accountType:string;roles:string[];permissions:string[]}};
async function api(path:string,init:RequestInit={},s?:Session|null){const r=await fetch(API_BASE+'/api/v1'+path,{...init,headers:{'Content-Type':'application/json',...(s?{Authorization:`Bearer ${s.accessToken}`}:{ }),...(init.headers||{})}});if(!r.ok){const b=await r.json().catch(()=>({detail:r.statusText}));if(r.status===401&&s){localStorage.removeItem('session');window.location.reload()}throw new Error(b.detail||b.message||b.title||`${r.status} ${r.statusText}`)}return r.status===204?null:r.json()}
async function uploadApi(path:string,file:File,s:Session){const form=new FormData();form.append('file',file);const r=await fetch(API_BASE+'/api/v1'+path,{method:'POST',headers:{Authorization:`Bearer ${s.accessToken}`},body:form});const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.detail||body.message||`Image upload failed (${r.status})`);return body}
const send=(path:string,body:any,s:Session,method='POST',headers={})=>api(path,{method,body:body===undefined?undefined:JSON.stringify(body),headers},s);
function App(){
 useEffect(()=>{if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});},[]);
 const[s,setS]=useState<Session|null>(()=>JSON.parse(localStorage.getItem('session')||'null'));
 const[msg,setMsg]=useState('');
 const[mode,setMode]=useState<'home'|'login'|'register'|'forgot'|'reset'|'mfa'>(()=>new URLSearchParams(window.location.search).has('resetToken')?'reset':'home');
 const[resetToken,setResetToken]=useState(()=>new URLSearchParams(window.location.search).get('resetToken')||'');const[mfaChallengeId,setMfaChallengeId]=useState('');
 const saveSession=(x:Session)=>{localStorage.setItem('session',JSON.stringify(x));setS(x);setMode('login');setMsg('')};
 const login=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;try{const x=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(x.mfaRequired){setMfaChallengeId(x.challengeId);setMode('mfa');setMsg('A verification code was sent to your platform administrator email.')}else saveSession(x)}catch(e:any){setMsg(e.message)}};
 const verifyMfa=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;try{const values=Object.fromEntries(new FormData(form));const x=await api('/auth/mfa/verify',{method:'POST',body:JSON.stringify({...values,challengeId:mfaChallengeId})});saveSession(x);setMfaChallengeId('')}catch(e:any){setMsg(e.message)}};
 const register=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;try{const x=await api('/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});saveSession(x)}catch(e:any){setMsg(e.message)}};
 const forgot=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;try{const x=await api('/auth/forgot-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});setMsg(x.message||'If the account exists, reset instructions were sent. Check your email.');setMode('reset')}catch(e:any){setMsg(e.message)}};
 const reset=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;try{await api('/auth/reset-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});setMsg('Password reset. Please sign in with your new password.');setMode('login');setResetToken('');window.history.replaceState({},'',window.location.pathname)}catch(e:any){setMsg(e.message)}};
 const logout=async()=>{try{if(s?.refreshToken)await send('/auth/logout',{refreshToken:s.refreshToken},s)}catch(e:any){setMsg('Server logout failed; local session cleared. '+e.message)}finally{localStorage.removeItem('session');setS(null);setMode('home')}};
 return <>{s?<header className="authenticated-header"><button type="button" className="brand-home" aria-label="Go to your home dashboard" onClick={()=>window.location.assign('/')}><img className="brand-logo" src="https://soumya-solar-energy-solution.vercel.app/images/soumya-solar-brand.svg" alt="Soumya Solar Energy Solution"/></button><span>{s.user.name} · {s.user.accountType}</span><button onClick={logout}>Logout</button></header>:mode!=='home'?<header className="auth-header"><a href="/" className="brand-home" aria-label="Back to public home"><img className="brand-logo" src="https://soumya-solar-energy-solution.vercel.app/images/soumya-solar-brand.svg" alt="Soumya Solar Energy Solution"/></a></header>:null}{msg&&<div className="notice">{msg}<button onClick={()=>setMsg('')}>×</button></div>}<main>{!s?mode==='home'?<PublicHome onLogin={()=>setMode('login')} onRegister={()=>setMode('register')}/>:mode==='login'?<form className="card form" onSubmit={login}><h1>Sign in</h1><input name="email" type="email" placeholder="Email" required/><input name="password" type="password" placeholder="Password" required/><button>Login</button><button type="button" onClick={()=>setMode('register')}>Create customer account</button><button type="button" onClick={()=>setMode('forgot')}>Forgot password?</button></form>:mode==='mfa'?<form className="card form" onSubmit={verifyMfa}><h1>Verify sign in</h1><p className="muted">Enter the 6-digit code sent to your platform administrator email. The code expires in 5 minutes.</p><input name="code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} placeholder="6-digit code" required/><button>Verify and continue</button><button type="button" onClick={()=>{setMode('login');setMfaChallengeId('')}}>Cancel</button></form>:mode==='register'?<form className="card form" onSubmit={register}><h1>Customer registration</h1><p className="muted">Enter the vendor store slug or its exact display name.</p><input name="storeSlug" placeholder="Vendor store slug or store name" defaultValue="saumya-solar" required/><input name="name" placeholder="Full name" required/><input name="email" type="email" placeholder="Email" required/><input name="password" type="password" placeholder="Password (12+ characters)" minLength={12} required/><button>Create account</button><button type="button" onClick={()=>setMode('login')}>Back to sign in</button></form>:mode==='forgot'?<form className="card form" onSubmit={forgot}><h1>Reset password</h1><input name="email" type="email" placeholder="Account email" required/><button>Request reset</button><button type="button" onClick={()=>setMode('login')}>Back to sign in</button></form>:<form className="card form" onSubmit={reset}><h1>Choose a new password</h1><input name="token" placeholder="Reset token" defaultValue={resetToken} required/><input name="newPassword" type="password" placeholder="New password (12+ characters)" minLength={12} required/><button>Reset password</button><button type="button" onClick={()=>setMode('login')}>Back to sign in</button></form>:s.user.accountType==='PLATFORM'?<><Platform s={s} error={setMsg}/>{s.user.permissions?.includes("SUBSCRIPTION_MANAGE")&&<EnterpriseSaasPanel mode="platform" s={s} error={setMsg}/>}</>:s.user.accountType==='CUSTOMER'?<Customer s={s} error={setMsg}/>:<><Vendor s={s} error={setMsg}/>{["BRANCH_MANAGE","BRANDING_MANAGE","AUDIT_VIEW","APPROVAL_WORKFLOW_MANAGE"].some(permission=>s.user.permissions?.includes(permission))&&<EnterpriseSaasPanel mode="vendor" s={s} error={setMsg}/>}</>}</main>{s&&['VENDOR','CUSTOMER'].includes(s.user.accountType)&&<OfflineSyncPanel session={s}/>}</>}
function Platform({s,error}:any){
 const [data,setData]=useState<any>({items:[],recentlyCreated:[],total:0,totalPages:0,active:0,inactive:0,suspended:0});
 const [search,setSearch]=useState('');const [status,setStatus]=useState('ALL');const [page,setPage]=useState(0);const [loading,setLoading]=useState(true);
 const [view,setView]=useState<'dashboard'|'create'|'edit'|'detail'>('dashboard');const [selected,setSelected]=useState<any>(null);const [saving,setSaving]=useState(false);
 const load=async()=>{setLoading(true);try{const q=new URLSearchParams({search,status,page:String(page),size:'20'});setData(await api('/platform/tenants?'+q.toString(),{},s))}catch(e:any){error(e.message)}finally{setLoading(false)}};
 useEffect(()=>{void load()},[search,status,page]);
 const create=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const x:any=Object.fromEntries(new FormData(form));setSaving(true);try{await send('/tenants',x,s);form.reset();setView('dashboard');setPage(0);error('Tenant created successfully.');await load()}catch(e:any){error(e.message)}finally{setSaving(false)}};
 const update=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const x:any=Object.fromEntries(new FormData(form));setSaving(true);try{await send('/platform/tenants/'+selected.id,{name:x.name},s,'PATCH');setView('dashboard');setSelected(null);error('Tenant updated successfully.');await load()}catch(e:any){error(e.message)}finally{setSaving(false)}};
 const changeStatus=async(t:any)=>{const next=t.status==='ACTIVE'?'SUSPENDED':'ACTIVE';if(!window.confirm((next==='ACTIVE'?'Activate':'Suspend')+' '+t.name+'?'))return;try{await send('/tenants/'+t.id+'/status',{status:next},s,'PATCH');error('Tenant status updated.');await load()}catch(e:any){error(e.message)}};
 const download=async(format:string)=>{try{const q=new URLSearchParams({search,status});const suffix=format==='csv'?'':'.'+format;const r=await fetch(API_BASE+'/api/v1/platform/tenants/export'+suffix+'?'+q.toString(),{headers:{Authorization:'Bearer '+s.accessToken}});if(!r.ok){const body=await r.json().catch(()=>({}));throw Error(body.detail||'Tenant export failed ('+r.status+')')}const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='tenants-'+status.toLowerCase()+'-'+new Date().toISOString().slice(0,10)+'.'+format;a.click();URL.revokeObjectURL(url)}catch(e:any){error(e.message)}};
 if(view==='create')return <section className="platform-shell"><button className="secondary" onClick={()=>setView('dashboard')}>← Back to dashboard</button><form className="card form" onSubmit={create}><h1>Create tenant</h1><input name="name" placeholder="Vendor / tenant name" required maxLength={150}/><input name="slug" placeholder="Store slug (for example, janhvi-solar)" required maxLength={100}/><input name="adminName" placeholder="Vendor administrator name" required/><input name="adminEmail" type="email" placeholder="Administrator email" required/><input name="adminPassword" type="password" minLength={12} placeholder="Temporary password (12+ characters)" required/><button disabled={saving}>{saving?'Creating…':'Create tenant'}</button></form></section>;
 if(view==='edit'&&selected)return <section className="platform-shell"><button className="secondary" onClick={()=>setView('dashboard')}>← Back to dashboard</button><form className="card form" onSubmit={update}><h1>Edit tenant</h1><label>Tenant name<input name="name" defaultValue={selected.name} required maxLength={150}/></label><label>Tenant slug<input value={selected.slug} disabled readOnly/><small>Tenant slug and administrator identity are immutable after provisioning.</small></label><label>Administrator<input value={selected.administratorName||'—'} disabled readOnly/></label><label>Administrator email<input value={selected.administratorEmail||'—'} disabled readOnly/></label><button disabled={saving}>{saving?'Saving…':'Save changes'}</button></form></section>;
 if(view==='detail'&&selected)return <section className="platform-shell"><button className="secondary" onClick={()=>setView('dashboard')}>← Back to dashboard</button><div className="card"><h1>{selected.name}</h1><p>Slug: {selected.slug}</p><p>Administrator: {selected.administratorName||'—'} · {selected.administratorEmail||'—'}</p><p>Status: {selected.status}</p><p>Created: {selected.createdAt||'—'}</p><p>Updated: {selected.updatedAt||'—'}</p><button onClick={()=>setView('edit')}>Edit tenant</button></div></section>;
 return <section className="platform-shell"><div className="platform-heading"><div><p className="eyebrow">PLATFORM ADMINISTRATION</p><h1>Platform dashboard</h1><p className="muted">Manage vendors, tenant access and onboarding.</p></div><button onClick={()=>setView('create')}>＋ Create Tenant</button></div>
 <div className="platform-stats"><article className="card"><small>Total tenants</small><strong>{data.total}</strong></article><article className="card"><small>Active</small><strong>{data.active}</strong></article><article className="card"><small>Inactive</small><strong>{data.inactive}</strong></article><article className="card"><small>Suspended</small><strong>{data.suspended}</strong></article></div>
 <div className="card"><div className="platform-heading"><h2>Tenant directory</h2><div className="actions"><button className="secondary" onClick={()=>download('xlsx')}>Excel</button><button className="secondary" onClick={()=>download('csv')}>CSV</button><button className="secondary" onClick={()=>download('pdf')}>PDF</button></div></div>
 <div className="platform-filters"><input aria-label="Search tenants" placeholder="Search tenant, slug, admin name or email" value={search} onChange={e=>{setPage(0);setSearch(e.target.value)}}/><select aria-label="Tenant status" value={status} onChange={e=>{setPage(0);setStatus(e.target.value)}}><option value="ALL">All statuses</option><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option><option value="SUSPENDED">Suspended</option></select></div>
 {loading?<p>Loading tenants…</p>:data.items.length===0?<div className="empty-state"><h3>No tenants found</h3><p>Try changing your search or status filter, or create a tenant.</p></div>:<div className="table-wrap"><table><thead><tr><th>Tenant</th><th>Slug</th><th>Administrator</th><th>Status</th><th>Created</th><th>Updated</th><th>Actions</th></tr></thead><tbody>{data.items.map((t:any)=><tr key={t.id}><td>{t.name}</td><td>{t.slug}</td><td>{t.administratorName||'—'}<small>{t.administratorEmail||''}</small></td><td><span className={'status-pill '+String(t.status).toLowerCase()}>{t.status}</span></td><td>{t.createdAt?new Date(t.createdAt).toLocaleDateString(): '—'}</td><td>{t.updatedAt?new Date(t.updatedAt).toLocaleDateString():'—'}</td><td><div className="actions"><button className="secondary" onClick={async()=>{try{setSelected(await api('/platform/tenants/'+t.id,{},s));setView('detail')}catch(e:any){error(e.message)}}}>View</button><button className="secondary" onClick={()=>{setSelected(t);setView('edit')}}>Edit</button><button className="secondary" onClick={()=>changeStatus(t)}>{t.status==='ACTIVE'?'Suspend':'Activate'}</button></div></td></tr>)}</tbody></table></div>}
 <div className="platform-pagination"><span>{data.total} tenants · Page {data.totalPages?data.page+1:0} of {data.totalPages}</span><div className="actions"><button className="secondary" disabled={page<=0||loading} onClick={()=>setPage(v=>v-1)}>Previous</button><button className="secondary" disabled={page+1>=data.totalPages||loading} onClick={()=>setPage(v=>v+1)}>Next</button></div></div></div>
 <div className="card"><h2>Recently created tenants</h2>{data.recentlyCreated?.length?data.recentlyCreated.map((t:any)=><article key={t.id}><div><b>{t.name}</b><small>{t.slug} · {t.createdAt?new Date(t.createdAt).toLocaleString():'Date unavailable'}</small></div><span>{t.status}</span></article>):<p>No tenants have been created yet.</p>}</div></section>;
}
function Vendor({s,error}:any){const p=s.user.permissions||[];const tabs:string[]=[];if(p.includes('CATALOG_MANAGE'))tabs.push('categories','products','packages');if(p.includes('CUSTOMER_MANAGE'))tabs.push('customers');if(p.includes('LEAD_MANAGE'))tabs.push('enquiries','leads');if(p.includes('SURVEY_MANAGE'))tabs.push('surveys');if(p.includes('QUOTATION_MANAGE'))tabs.push('quotations');if(p.includes('ORDER_CREATE'))tabs.push('orders');if(p.includes('USER_VIEW'))tabs.push('users');if(p.includes('DISCOUNT_POLICY_MANAGE'))tabs.push('settings');if(p.includes('INVENTORY_MANAGE')||p.includes('SURVEY_MANAGE'))tabs.push('operations');if(p.includes('FINANCE_MANAGE')||p.includes('SERVICE_MANAGE'))tabs.push('finance-service');return <Crud title="Vendor Portal" s={s} error={error} tabs={tabs} forms={{users:['name','email','password','roleName'],categories:['name','description'],products:['sku','name','categoryId','manufacturer','model','technology','description','purchasePrice','price','discountPercent','taxPercent','warrantyYears','imageUrl','datasheetUrl','reorderLevel','unitOfMeasure','hsnCode','serialized','attributesJson'],packages:['code','name','capacityKw','packageType','basePrice','warrantyYears'],customers:['name','email','phone','address'],enquiries:['name','email','phone','propertyType','monthlyBill','requiredCapacityKw','message']}}/>}
function SettingsForm({s,error}:any){
 const [threshold,setThreshold]=useState('10');
 const [saving,setSaving]=useState(false);
 const [loading,setLoading]=useState(true);
 const [loadError,setLoadError]=useState('');
 useEffect(()=>{let alive=true;api('/settings',{},s).then((x:any)=>{if(alive)setThreshold(String(x.discountApprovalThreshold??10))}).catch((e:any)=>{if(alive)setLoadError(e.message||'Unable to load vendor settings')}).finally(()=>{if(alive)setLoading(false)});return()=>{alive=false}},[s.accessToken]);
 const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setSaving(true);setLoadError('');try{const x=await send('/settings/discount-threshold',{discountPercent:Number(threshold)},s,'PATCH');setThreshold(String(x.discountApprovalThreshold));error('Discount approval threshold saved.')}catch(e:any){setLoadError(e.message||'Unable to save settings')}finally{setSaving(false)}};
 if(loading)return <section className="card settings-state" aria-live="polite"><h2>Vendor settings</h2><p>Loading settings…</p></section>;
 if(loadError)return <section className="card settings-state error-state" role="alert"><h2>Vendor settings could not be loaded</h2><p>{loadError}</p><button type="button" onClick={()=>{setLoading(true);setLoadError('');void api('/settings',{},s).then((x:any)=>setThreshold(String(x.discountApprovalThreshold??10))).catch((e:any)=>setLoadError(e.message)).finally(()=>setLoading(false))}}>Retry</button></section>;
 return <form className="card form" onSubmit={submit}><h2>Quotation approval policy</h2><label>Discount percentage above which approval is required<input type="number" min="0" max="100" step="0.01" value={threshold} onChange={e=>setThreshold(e.target.value)} required/></label><p className="muted">Quotations with a discount greater than this percentage enter Pending Approval. The threshold applies only to this vendor.</p><button disabled={saving}>{saving?'Saving…':'Save policy'}</button></form>;
}

function Customer({s,error}:any){
 const [catalog,setCatalog]=useState<any>({categories:[],products:[],packages:[]});
 const [quotes,setQuotes]=useState<any[]>([]);
 const [orders,setOrders]=useState<any[]>([]);
 const [enquiries,setEnquiries]=useState<any[]>([]);
 const [installations,setInstallations]=useState<any[]>([]);
 const [warranties,setWarranties]=useState<any[]>([]);const [warrantyClaims,setWarrantyClaims]=useState<any[]>([]);const [messagingConsent,setMessagingConsent]=useState<any>({smsConsent:false,whatsappConsent:false});const [invoices,setInvoices]=useState<any[]>([]);const [payments,setPayments]=useState<any[]>([]);const [serviceTickets,setServiceTickets]=useState<any[]>([]);const [serviceAttachments,setServiceAttachments]=useState<any>({});const [serviceComments,setServiceComments]=useState<any>({});const [gatewayAvailability,setGatewayAvailability]=useState<any>({available:false,providers:[]});
 const [busy,setBusy]=useState(false);
 const [tab,setTab]=useState('catalog');const[productSearch,setProductSearch]=useState('');const[categoryFilter,setCategoryFilter]=useState('ALL');const[brandFilter,setBrandFilter]=useState('ALL');const[minPrice,setMinPrice]=useState('');const[maxPrice,setMaxPrice]=useState('');const visibleProducts=catalog.products.filter((p:any)=>{const q=productSearch.trim().toLowerCase();const text=[p.name,p.description,p.sku,p.manufacturer,p.model,p.technology].filter(Boolean).join(' ').toLowerCase();const price=Number(p.price||0);return(!q||text.includes(q))&&(categoryFilter==='ALL'||p.categoryId===categoryFilter)&&(brandFilter==='ALL'||p.manufacturer===brandFilter)&&(minPrice===''||price>=Number(minPrice))&&(maxPrice===''||price<=Number(maxPrice))});
 const load=async()=>{
  setBusy(true);
  try{
   const [categories,products,packages,q,o,e,i,w,inv,pay,svc,claims,consent,gateway]=await Promise.all([
    api('/catalog-categories',{},s),api('/catalog-products',{},s),api('/catalog-packages',{},s),
    api('/quotations',{},s),api('/customer-orders',{},s),api('/customer-enquiries',{},s),
    api('/customer/installations',{},s),api('/customer/warranties',{},s),api('/invoices',{},s),api('/payments',{},s),api('/service-requests',{},s),api('/customer/warranty-claims',{},s),api('/customer/messaging-consent',{},s),api('/payment-gateways/availability',{},s).catch(()=>({available:false,providers:[]}))
   ]);
   setCatalog({categories,products,packages});setQuotes(q||[]);setOrders(o||[]);setEnquiries(e||[]);setInstallations(i||[]);setWarranties(w||[]);setWarrantyClaims(claims||[]);setMessagingConsent(consent||{smsConsent:false,whatsappConsent:false});setInvoices(inv||[]);setPayments(pay||[]);setServiceTickets(svc||[]);const evidence=await Promise.all((svc||[]).map(async(ticket:any)=>[ticket.id,await api('/service-requests/'+ticket.id+'/attachments',{},s).catch(()=>[])]));setServiceAttachments(Object.fromEntries(evidence));const commentRows=await Promise.all((svc||[]).map(async(ticket:any)=>[ticket.id,await api('/service-requests/'+ticket.id+'/comments',{},s).catch(()=>[])]));setServiceComments(Object.fromEntries(commentRows));setGatewayAvailability(gateway||{available:false,providers:[]});
  }catch(err:any){error(err.message)}finally{setBusy(false)}
 };
 useEffect(()=>{void load()},[]);
 const requestQuote=async(e:React.FormEvent<HTMLFormElement>)=>{
  e.preventDefault();const form=e.currentTarget;const f:any=Object.fromEntries(new FormData(form));
  try{await send('/customer/enquiries',{propertyType:f.propertyType,monthlyBill:f.monthlyBill?Number(f.monthlyBill):null,requiredCapacityKw:f.requiredCapacityKw?Number(f.requiredCapacityKw):null,message:f.message},s);form.reset();setTab('enquiries');await load()}
  catch(err:any){error(err.message)}
 };
 const decision=async(id:string,choice:'accept'|'reject')=>{try{await send(`/quotations/${id}/${choice}`,{},s);await load()}catch(err:any){error(err.message)}};
 const startOnlineCheckout=async(invoice:any)=>{
  try{
   const key=sessionStorage.getItem('payment-checkout-key-'+invoice.id)||crypto.randomUUID();
   sessionStorage.setItem('payment-checkout-key-'+invoice.id,key);
   const result=await send('/payment-gateways/invoices/'+invoice.id+'/checkout',{},s,'POST',{'Idempotency-Key':key});
   if(!result.checkoutUrl)throw new Error('Payment provider did not return a checkout URL');
   window.location.assign(result.checkoutUrl);
  }catch(e:any){error(e.message)}
 };
 const uploadServiceEvidence=async(ticket:any,file?:File)=>{if(!file)return;const form=new FormData();form.append('file',file);try{const r=await fetch(API_BASE+'/api/v1/service-requests/'+ticket.id+'/attachments',{method:'POST',headers:{Authorization:'Bearer '+s.accessToken},body:form});if(!r.ok){const x=await r.json().catch(()=>({}));throw Error(x.detail||'Attachment upload failed')}await load();error('Evidence uploaded successfully.')}catch(e:any){error(e.message)}};
 const downloadServiceEvidence=async(ticket:any,item:any)=>{try{const r=await fetch(API_BASE+'/api/v1/service-requests/'+ticket.id+'/attachments/'+item.id,{headers:{Authorization:'Bearer '+s.accessToken}});if(!r.ok)throw Error('Attachment download failed');const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download=item.originalName;a.click();URL.revokeObjectURL(u)}catch(e:any){error(e.message)}};

 return <><h1>Customer Portal</h1><div className="tabs">{['catalog','request','enquiries','quotations','customer-orders','my-installations','warranties','warranty-claims','notifications','invoices','payments','service'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x==='customer-orders'?'My Orders':x==='my-installations'?'My Installations':x==='warranties'?'My Warranties':x==='warranty-claims'?'Warranty Claims':x==='notifications'?'Notification Preferences':x==='invoices'?'My Invoices':x==='payments'?'My Payments':x==='service'?'Service Requests':x==='request'?'Request a Solar Quotation':x==='catalog'?'Our Products':x==='enquiries'?'My Enquiries':'My Quotations'}</button>)}</div>
 {busy&&<p>Loading your solar workspace…</p>}
 {tab==='catalog'&&<><section className="card customer-catalog"><div className="table-toolbar"><div><h2>Available products</h2><span>{visibleProducts.length} products</span></div><input aria-label="Search products" placeholder="Search name, keyword or description" value={productSearch} onChange={e=>setProductSearch(e.target.value)}/></div><div className="catalog-filters"><select value={categoryFilter} onChange={e=>setCategoryFilter(e.target.value)}><option value="ALL">All categories</option>{catalog.categories.map((c:any)=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select value={brandFilter} onChange={e=>setBrandFilter(e.target.value)}><option value="ALL">All brands</option>{Array.from(new Set(catalog.products.map((p:any)=>p.manufacturer).filter(Boolean))).map((v:any)=><option key={v} value={v}>{v}</option>)}</select><input type="number" min="0" placeholder="Min price" value={minPrice} onChange={e=>setMinPrice(e.target.value)}/><input type="number" min="0" placeholder="Max price" value={maxPrice} onChange={e=>setMaxPrice(e.target.value)}/><button type="button" className="secondary" onClick={()=>{setProductSearch('');setCategoryFilter('ALL');setBrandFilter('ALL');setMinPrice('');setMaxPrice('')}}>Reset filters</button></div>{visibleProducts.length?visibleProducts.map((x:any)=><article className="catalog-product" key={x.id}>{x.imageUrl&&<img src={x.imageUrl} alt={x.name} loading="lazy"/>}<div><b>{x.name}</b><small>{catalog.categories.find((v:any)=>v.id===x.categoryId)?.name||'Solar product'} · {x.sku} · {x.manufacturer||'Demo manufacturer'}</small><small>{x.technology||''} · {x.model||''} · Warranty {x.warrantyYears??'—'} years</small></div><div className="product-price"><strong>₹{(Number(x.price||0)*(1-Number(x.discountPercent||0)/100)*(1+Number(x.taxPercent||0)/100)).toLocaleString('en-IN',{maximumFractionDigits:2})}</strong><small>Incl. {Number(x.taxPercent||0)}% GST · {x.hsnCode||'HSN not set'}</small>{Number(x.discountPercent||0)>0&&<><del>₹{(Number(x.price)*(1+Number(x.taxPercent||0)/100)).toLocaleString('en-IN')}</del><small>{x.discountPercent}% discount</small></>}<button type="button" onClick={async()=>{if(!window.confirm('Place an order for '+x.name+'? The vendor must accept it before fulfilment.'))return;try{await send('/customer/product-orders',{productId:x.id,quantity:1},s);await load();setTab('customer-orders');error('Order request submitted. It is waiting for vendor acceptance.')}catch(e:any){error(e.message)}}}>Order now</button></div><details className="product-details"><summary>More Details</summary><p>{x.description||'No product description supplied.'}</p><p>Manufacturer: {x.manufacturer||'—'} · Model: {x.model||'—'} · Technology: {x.technology||'—'}</p><p>Warranty: {x.warrantyYears??'—'} years · Unit: {x.unitOfMeasure||'PCS'}</p>{x.attributesJson&&<pre>{x.attributesJson}</pre>}{x.datasheetUrl&&<a href={x.datasheetUrl} target="_blank" rel="noreferrer">Product datasheet</a>}</details></article>):<p>No products are published yet.</p>}</section><section className="card"><h2>Solar packages</h2>{catalog.packages.length?catalog.packages.map((x:any)=><article className="customer-package-card" key={x.id}><img src={assetUrl(x.imageUrl)} alt={x.name} onError={e=>{e.currentTarget.src='https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=900&q=80'}}/><div><b>{x.name}</b><small>{x.capacityKw} kW · {x.packageType} · {x.warrantyYears??'—'} year warranty</small></div><strong>₹{Number(x.basePrice||0).toLocaleString('en-IN')}</strong></article>):<p>No packages are published yet.</p>}</section></>}
 {tab==='request'&&<form className="card form" onSubmit={requestQuote}><h2>Request a Solar Quotation</h2><input name="propertyType" placeholder="Property type (Residential / Commercial)"/><input name="monthlyBill" type="number" min="0" step="0.01" placeholder="Monthly electricity bill (₹)"/><input name="requiredCapacityKw" type="number" min="0.1" step="0.1" placeholder="Required capacity (kW)"/><textarea name="message" placeholder="Roof type, roof area, location and requirements"/><button>Submit enquiry</button></form>}
 {tab==='enquiries'&&<section className="card"><h2>My Enquiries</h2>{enquiries.length?enquiries.map((x:any)=><article key={x.id}><div><b>{x.propertyType||'Solar enquiry'}</b><small>{x.status} · {x.createdAt||''}</small></div><span>{x.requiredCapacityKw||'—'} kW</span></article>):<p>You have not submitted an enquiry yet.</p>}</section>}
 {tab==='quotations'&&<section className="card"><h2>My Quotations</h2>{quotes.length?quotes.map((x:any)=><article key={x.id}><div><b>{x.quotationNumber}</b><small>Revision {x.revision} · {x.status} · Valid until {x.validUntil}</small></div><div className="actions"><strong>₹{x.grandTotal}</strong>{x.status==='SENT'&&<><button onClick={()=>decision(x.id,'accept')}>Accept</button><button onClick={()=>decision(x.id,'reject')}>Reject</button></>}</div></article>):<p>No quotations are available yet. Submit an enquiry to get started.</p>}</section>}
 {tab==='customer-orders'&&<section className="card management-list"><div className="table-toolbar"><h2>My Orders · {orders.length}</h2></div>{orders.length?<div className="table-wrap"><table className="management-table"><thead><tr><th>Order Number</th><th>Order Date</th><th>Product / Package</th><th>Amount</th><th>Payment Status</th><th>Order Status</th></tr></thead><tbody>{orders.map((x:any)=><tr key={x.id}><td><strong>{x.orderNumber}</strong></td><td>{x.createdAt||x.orderDate?new Date(x.createdAt||x.orderDate).toLocaleDateString():'—'}</td><td>{x.items?.map((i:any)=>i.productName||i.packageName||i.name).filter(Boolean).join(', ')||x.productName||x.packageName||'—'}</td><td>₹{Number(x.total||x.grandTotal||0).toLocaleString('en-IN')}</td><td><span className={'status-pill '+String(x.paymentStatus||'unknown').toLowerCase()}>{x.paymentStatus||'—'}</span></td><td><span className={'status-pill '+String(x.status||'unknown').toLowerCase()}>{x.status||'—'}</span></td></tr>)}</tbody></table></div>:<div className="table-state">No orders yet. Accepted quotations will appear here after conversion.</div>}</section>}
 {tab==='my-installations'&&<section className="card"><h2>My Installations</h2>{installations.length?installations.map((x:any)=><article key={x.id}><div><b>{x.siteAddress}</b><small>{x.status} · Scheduled {x.scheduledAt}</small></div><span>{x.capacityKw||'—'} kW</span></article>):<p>No installation jobs have been scheduled for your orders yet.</p>}</section>}
 {tab==='invoices'&&<section className="card"><h2>My Invoices</h2>{invoices.length?invoices.map((x:any)=><article key={x.id}><div><b>{x.invoiceNumber}</b><small>{x.status} · Issued {x.issuedAt?new Date(x.issuedAt).toLocaleDateString():'—'}</small></div><div className="actions"><strong>₹{x.grandTotal}</strong>{['ISSUED','PARTIALLY_PAID'].includes(x.status)&&(gatewayAvailability.available?<button type="button" onClick={()=>void startOnlineCheckout(x)}>Pay online</button>:<small className="muted">Online payment is not configured for this store.</small>)}<button type="button" onClick={async()=>{try{const r=await fetch(API_BASE+'/api/v1/invoices/'+x.id+'/pdf',{headers:{Authorization:'Bearer '+s.accessToken}});if(!r.ok)throw Error('Invoice PDF download failed');const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download=x.invoiceNumber+'.pdf';a.click();URL.revokeObjectURL(u)}catch(e:any){error(e.message)}}}>Download PDF</button></div></article>):<p>No invoices have been issued for your orders yet.</p>}</section>}
 {tab==='payments'&&<section className="card"><h2>My Payments and Receipts</h2>{payments.length?payments.map((x:any)=><article key={x.id}><div><b>₹{x.amount} · {x.status}</b><small>{x.method} · {x.paidAt?new Date(x.paidAt).toLocaleString():''} · {x.reference||x.providerReference||'No reference'}</small></div><button type="button" onClick={async()=>{try{const r=await fetch(API_BASE+'/api/v1/payments/'+x.id+'/receipt.pdf',{headers:{Authorization:'Bearer '+s.accessToken}});if(!r.ok)throw Error('Receipt download failed');const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download='payment-receipt-'+x.id+'.pdf';a.click();URL.revokeObjectURL(u)}catch(e:any){error(e.message)}}}>Download receipt</button></article>):<p>No payments recorded yet.</p>}</section>}
 {tab==='service'&&<><form className="card form" onSubmit={async e=>{e.preventDefault();const form=e.currentTarget;const f:any=Object.fromEntries(new FormData(form));try{await send('/service-requests',{category:f.category,priority:f.priority,description:f.description,installationId:f.installationId||null,productId:f.productId||null,serialNumber:f.serialNumber||null},s);form.reset();await load();setTab('service');error('Service request submitted.')}catch(x:any){error(x.message)}}}><h2>Raise a Service Request</h2><input name="category" placeholder="Service category" required/><select name="priority"><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select><textarea name="description" placeholder="Describe the issue" required/><select name="installationId" defaultValue=""><option value="">Related installation (optional)</option>{installations.map((x:any)=><option key={x.id} value={x.id}>{x.siteAddress} · {x.status}</option>)}</select><input name="productId" placeholder="Product ID (optional)"/><input name="serialNumber" placeholder="Product serial number (optional)"/><button>Submit service request</button></form><section className="card"><h2>My Service Requests</h2>{serviceTickets.length?serviceTickets.map((x:any)=><article key={x.id}><div><b>{x.ticketNumber} · {x.category}</b><small>{x.status} · {x.priority} · {x.warrantyStatus}</small><small>{x.description}</small><div className="service-comments"><b>Comments and updates</b>{(serviceComments[x.id]||[]).map((v:any)=><small key={v.id}>{v.body} · {new Date(v.createdAt).toLocaleString()}</small>)}<button type="button" className="secondary" onClick={async()=>{const body=window.prompt("Add a comment to this service request");if(!body?.trim())return;try{await send("/service-requests/"+x.id+"/comments",{body,visibility:"CUSTOMER"},s);await load()}catch(e:any){error(e.message)}}}>Add comment</button></div><div className="service-attachments"><label>Add photo or document<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" onChange={e=>uploadServiceEvidence(x,e.target.files?.[0])}/></label>{(serviceAttachments[x.id]||[]).map((a:any)=><button type="button" className="secondary" key={a.id} onClick={()=>downloadServiceEvidence(x,a)}>{a.originalName}</button>)}</div></div><div className="actions">{x.status==='RESOLVED'&&<button onClick={async()=>{try{await send('/service-requests/'+x.id+'/confirm',{},s);await load()}catch(e:any){error(e.message)}}}>Confirm resolution</button>}{x.status==='CLOSED'&&<button className="secondary" onClick={async()=>{const reason=window.prompt('Reason to reopen this ticket');if(!reason?.trim())return;try{await send('/service-requests/'+x.id+'/reopen',{reason},s);await load()}catch(e:any){error(e.message)}}}>Request reopen</button>}</div></article>):<p>No service tickets. Submit a request if your solar system needs support.</p>}</section></>}

 {tab==='warranty-claims'&&<><form className="card form" onSubmit={async e=>{e.preventDefault();const form=e.currentTarget;const f:any=Object.fromEntries(new FormData(form));try{await send('/customer/warranty-claims',{warrantyId:f.warrantyId,subject:f.subject,description:f.description,evidenceUrl:f.evidenceUrl||null},s);form.reset();await load();error('Warranty claim submitted.')}catch(x:any){error(x.message)}}}><h2>Submit Warranty Claim</h2><select name="warrantyId" required defaultValue=""><option value="">Select active warranty</option>{warranties.filter((w:any)=>w.status==='ACTIVE').map((w:any)=><option key={w.id} value={w.id}>{catalog.products.find((p:any)=>p.id===w.productId)?.name||w.productId} · {w.serialNumber||'No serial'} · expires {w.endDate}</option>)}</select><input name="subject" placeholder="Claim subject" required/><textarea name="description" placeholder="Describe the defect or issue" required/><input name="evidenceUrl" type="url" placeholder="Evidence URL (optional)"/><button>Submit claim</button></form><section className="card"><h2>Claim history</h2>{warrantyClaims.length?warrantyClaims.map((x:any)=><article key={x.id}><div><b>{x.claimNumber} · {x.subject}</b><small>{x.status} · {new Date(x.createdAt).toLocaleString()}</small><small>{x.decisionReason||x.resolutionNotes||x.description}</small></div></article>):<p>No warranty claims submitted.</p>}</section></>}
 {tab==='notifications'&&<form className="card form" onSubmit={async e=>{e.preventDefault();try{const x={smsConsent:(e.currentTarget.elements.namedItem('smsConsent') as HTMLInputElement).checked,whatsappConsent:(e.currentTarget.elements.namedItem('whatsappConsent') as HTMLInputElement).checked};await send('/customer/messaging-consent',x,s,'PATCH');setMessagingConsent(x);error('Notification preferences saved.')}catch(x:any){error(x.message)}}}><h2>Notification Preferences</h2><p>Choose whether the vendor may send service and order updates to your registered phone number. Your consent is optional and can be changed at any time.</p><label className="check-row"><input type="checkbox" name="smsConsent" defaultChecked={messagingConsent.smsConsent}/> SMS notifications</label><label className="check-row"><input type="checkbox" name="whatsappConsent" defaultChecked={messagingConsent.whatsappConsent}/> WhatsApp notifications</label><button>Save preferences</button><small>SMS and WhatsApp delivery requires the vendor to configure an approved provider and sender identity.</small></form>}
 {tab==='warranties'&&<section className="card"><h2>My Product Warranties</h2>{warranties.length?warranties.map((x:any)=><article key={x.id}><div><b>{catalog.products.find((p:any)=>p.id===x.productId)?.name||'Solar equipment'}</b><small>Serial: {x.serialNumber||'Not supplied'} · {x.status}</small></div><span>{x.startDate} to {x.endDate}</span></article>):<p>Warranties appear after installation commissioning and equipment registration.</p>}</section>}
 </>;
}
function Crud({title,s,error,tabs,forms}:any){
 const[tab,setTab]=useState(tabs[0]||'');
 const[data,setData]=useState<any[]>([]);
 const[lookups,setLookups]=useState<any>({});
 const[loading,setLoading]=useState(false);
 const[editing,setEditing]=useState<any>(null);const[detailRecord,setDetailRecord]=useState<any>(null);
 const[createOpen,setCreateOpen]=useState(false);
 const[search,setSearch]=useState('');
 const[statusFilter,setStatusFilter]=useState('ALL');
 const[sortKey,setSortKey]=useState('createdAt');
 const[sortDir,setSortDir]=useState<'asc'|'desc'>('desc');
 const[page,setPage]=useState(0);
 const pageSize=10;
 const labels:any={categories:'Category',products:'Product',packages:'Solar Package',customers:'Customer',enquiries:'Enquiry',leads:'Lead',surveys:'Site Survey',quotations:'Quotation',orders:'Order',users:'User',operations:'Operations','finance-service':'Finance & Service',settings:'Settings'};
 const refreshLookups=async()=>{if(s.user.accountType==='VENDOR'){const rows=await Promise.all(['categories','customers','leads','surveys','products','packages','users','roles'].map(async x=>[x,await api('/'+x,{},s).catch(()=>[])] as const));setLookups(Object.fromEntries(rows))}};
 const load=async()=>{if(!tab)return;setLoading(true);try{if(tab==='operations'||tab==='finance-service'||tab==='settings'){setData([]);await refreshLookups();return}setData(await api('/'+tab,{},s)||[]);await refreshLookups()}catch(e:any){error(e.message)}finally{setLoading(false)}};
 useEffect(()=>{setCreateOpen(false);setSearch('');setStatusFilter('ALL');setPage(0);setEditing(null);setDetailRecord(null);void load()},[tab]);
 const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const x:any=Object.fromEntries(new FormData(form));['price','purchasePrice','discountPercent','taxPercent','capacityKw','basePrice','warrantyYears','monthlyBill','requiredCapacityKw','reorderLevel'].forEach(k=>{if(x[k]!=='')x[k]=Number(x[k])});x.active=true;if(x.serialized!==undefined)x.serialized=x.serialized==='on'||x.serialized===true;if(tab==='products'){x.purchasePrice??=0;x.discountPercent??=0;x.taxPercent??=0;x.reorderLevel??=0;x.unitOfMeasure||='PCS'}try{await send(tab==='products'?'/catalog/products':'/'+tab,x,s);form.reset();setCreateOpen(false);await load();error('Record created successfully.')}catch(z:any){error(z.message)}};
 const action=async(path:string,body:any={},headers:any={})=>{try{await send(path,body,s,'POST',headers);await load()}catch(e:any){error(e.message)}};
 const columns:any={
  categories:[['name','Category'],['description','Description'],['active','Status']],
  products:[['sku','SKU'],['name','Product'],['categoryId','Category'],['manufacturer','Brand'],['model','Model'],['price','Price'],['active','Status']],
  packages:[['code','Code'],['name','Package'],['capacityKw','Capacity (kW)'],['packageType','Type'],['basePrice','Base price'],['active','Status']],
  customers:[['name','Customer'],['email','Email'],['phone','Phone'],['active','Status']],
  enquiries:[['name','Customer'],['email','Email'],['phone','Phone'],['propertyType','Property'],['requiredCapacityKw','Capacity (kW)'],['status','Status'],['createdAt','Created']],
  leads:[['name','Lead'],['email','Email'],['phone','Phone'],['stage','Stage'],['priority','Priority'],['nextFollowUp','Next follow-up']],
  surveys:[['surveyNumber','Survey #'],['customerName','Customer'],['siteAddress','Site address'],['scheduledAt','Scheduled'],['status','Status']],
  quotations:[['quotationNumber','Quotation #'],['revision','Revision'],['customerName','Customer'],['grandTotal','Amount'],['status','Status'],['createdAt','Created']],
  orders:[['orderNumber','Order #'],['customerName','Customer'],['total','Amount'],['paymentStatus','Payment'],['status','Order status'],['createdAt','Order date']],
  users:[['name','Name'],['email','Email'],['roles','Role'],['enabled','Status'],['createdAt','Created']]
 };
 const titleCase=(v:string)=>v.replace(/([A-Z])/g,' $1').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
 const cols=columns[tab]||[];
 const searchable=(x:any)=>Object.values(x||{}).filter(v=>v===null||['string','number','boolean'].includes(typeof v)).join(' ').toLowerCase();
 const hasStatus=data.some(x=>x.status!==undefined||x.enabled!==undefined||x.active!==undefined);
 const filtered=data.filter(x=>searchable(x).includes(search.toLowerCase())&&(statusFilter==='ALL'||String(x.status??(x.enabled??x.active?'ACTIVE':'INACTIVE')).toUpperCase()===statusFilter));
 const sorted=[...filtered].sort((a,b)=>{const av=a[sortKey]??'',bv=b[sortKey]??'';const an=Number(av),bn=Number(bv);const cmp=av!==''&&bv!==''&&Number.isFinite(an)&&Number.isFinite(bn)?an-bn:String(av).localeCompare(String(bv),undefined,{numeric:true,sensitivity:'base'});return sortDir==='asc'?cmp:-cmp});
 const pageRows=sorted.slice(page*pageSize,(page+1)*pageSize);
 const sort=(key:string)=>{setSortKey(key);setSortDir(v=>sortKey===key?(v==='asc'?'desc':'asc'):'asc')};
 const formatCell=(x:any,key:string)=>{const value=x[key];if(value===null||value===undefined||value==='')return '—';if(['active','enabled'].includes(key)||key==='status'||key==='paymentStatus'){const label=typeof value==='boolean'?(value?'Active':'Inactive'):String(value).replaceAll('_',' ');return <span className={'status-pill '+String(value).toLowerCase()}>{label}</span>}if(key==='categoryId')return lookups.categories?.find((c:any)=>c.id===value)?.name||value;if(key==='roles')return Array.isArray(value)?value.map((v:any)=>typeof v==='string'?v:v.name).join(', '):String(value);if(/date|at$|followUp/i.test(key)){const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleDateString()}if(['price','basePrice','grandTotal','total','amount'].includes(key))return '₹'+Number(value).toLocaleString('en-IN',{maximumFractionDigits:2});if(typeof value==='object')return JSON.stringify(value);return String(value)};
 const canCreate=!!forms[tab]||['packages','surveys','quotations'].includes(tab);
 const canManageUsers=tab!=='users'||s.user.permissions.includes('USER_MANAGE');
 const createLabel=labels[tab]||titleCase(tab);
 const renderActions=(x:any)=><div className="actions"><button type="button" className="secondary" onClick={()=>setDetailRecord(x)}>View</button>{tab==='packages'&&<PackageImageUpload packageId={x.id} token={s.accessToken} onUploaded={()=>load()} onError={error}/>}{['categories','products','customers','users'].includes(tab)&&<button type="button" className="secondary" onClick={()=>setEditing(x)}>Edit</button>}{['categories','products','customers','users','packages'].includes(tab)&&<button type="button" className="danger" onClick={async()=>{if(!window.confirm('Archive this '+createLabel.toLowerCase()+'? Existing order and quotation references will be retained.'))return;try{await api('/'+tab+'/'+x.id,{method:'DELETE'},s);error(createLabel+' archived successfully.');await load()}catch(e:any){error(e.message)}}}>Delete</button>}{tab==='users'&&s.user.permissions.includes('USER_MANAGE')&&<button type="button" className="secondary" onClick={()=>void send('/users/'+x.id+'/enabled',{active:!x.enabled},s,'PATCH').then(load).catch((e:any)=>error(e.message))}>{x.enabled?'Disable':'Enable'}</button>}{tab==='enquiries'&&x.status!=='CONVERTED'&&<button type="button" onClick={()=>action('/enquiries/'+x.id+'/convert',{priority:'MEDIUM'})}>Convert to Lead</button>}{tab==='leads'&&<><button type="button" onClick={()=>{const stage=prompt('Stage (NEW, CONTACTED, SITE_VISIT_SCHEDULED, SURVEY_COMPLETED, QUOTATION_SENT, NEGOTIATION, WON, LOST)',x.stage||'CONTACTED');if(!stage)return;const choices=(lookups.users||[]).filter((u:any)=>u.accountType==='VENDOR').map((u:any)=>u.name+' = '+u.id).join('\\n');const assignedUserId=prompt('Assigned employee ID. Available employees:\\n'+choices,x.assignedUserId||s.user.id);if(assignedUserId===null)return;const followUp=prompt('Next follow-up date/time (optional)',x.nextFollowUp||'');if(followUp===null)return;const lostReason=stage==='LOST'?prompt('Lost reason',x.lostReason||''):x.lostReason;void send('/leads/'+x.id,{stage,priority:x.priority,assignedUserId,nextFollowUp:followUp?new Date(followUp).toISOString():null,lostReason,reason:'Updated from UI'},s,'PATCH').then(load).catch((e:any)=>error(e.message))}}>Manage Lead</button><button type="button" className="secondary" onClick={()=>void api('/leads/'+x.id+'/history',{},s).then((rows:any[])=>window.alert(rows.map((r:any)=>r.eventType||'STAGE'+' · '+(r.oldStage||'—')+' → '+(r.newStage||'—')).join('\\n'))).catch((e:any)=>error(e.message))}>History</button></>}{tab==='quotations'&&s.user.accountType==='VENDOR'&&<>{x.status==='PENDING_APPROVAL'&&<button type="button" onClick={()=>action('/quotations/'+x.id+'/approve')}>Approve</button>}{x.status==='DRAFT'&&<button type="button" onClick={()=>action('/quotations/'+x.id+'/send')}>Send</button>}{['SENT','REJECTED','APPROVAL_REJECTED'].includes(x.status)&&<button type="button" onClick={()=>action('/quotations/'+x.id+'/revisions')}>New Revision</button>}{x.status==='ACCEPTED'&&<button type="button" onClick={()=>action('/quotations/'+x.id+'/convert-to-order',{}, {'Idempotency-Key':localStorage.getItem('order-key-'+x.id)||(()=>{const k=crypto.randomUUID();localStorage.setItem('order-key-'+x.id,k);return k})()})}>Convert to Order</button>}<button type="button" className="secondary" onClick={()=>void api('/quotations/'+x.id+'/revisions',{},s).then((rows:any[])=>window.alert(rows.map((v:any)=>'Revision '+v.revision+': '+v.status+' · ₹'+v.grandTotal).join('\\n'))).catch((e:any)=>error(e.message))}>History</button><button type="button" className="secondary" onClick={()=>downloadPdf(x,s,error)}>PDF</button></>}{tab==='quotations'&&s.user.accountType==='CUSTOMER'&&x.status==='SENT'&&<><button type="button" onClick={()=>action('/quotations/'+x.id+'/accept')}>Accept</button><button type="button" className="danger" onClick={()=>action('/quotations/'+x.id+'/reject')}>Reject</button><button type="button" className="secondary" onClick={()=>downloadPdf(x,s,error)}>PDF</button></>}</div>;
 return <section className="vendor-module-page"><div className="tabs module-tabs">{tabs.map((x:string)=><button type="button" key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{labels[x]||titleCase(x)}</button>)}</div><div className="management-heading"><div><p className="eyebrow">{title.toUpperCase()}</p><h1>{labels[tab]||titleCase(tab)}</h1><p className="muted">Manage and review your {labels[tab]?.toLowerCase()||tab.replaceAll('-',' ')} records.</p></div>{canCreate&&canManageUsers&&<button type="button" onClick={()=>setCreateOpen(v=>!v)}>{createOpen?'Close form':'+ Create '+createLabel}</button>}</div>{createOpen&&forms[tab]&&tab!=='packages'&&canManageUsers&&<form className="card form module-create-form" onSubmit={submit}><h2>Create {createLabel}</h2>{forms[tab].map((x:string)=>x==='categoryId'?<label key={x}>Product category<select name="categoryId" required defaultValue=""><option value="" disabled>Select category</option>{(lookups.categories||[]).filter((v:any)=>v.active).map((v:any)=><option key={v.id} value={v.id}>{v.name}</option>)}</select>{!(lookups.categories||[]).length&&<small>Create/seed a category before adding products.</small>}</label>:x==='roleName'?<label key={x}>Employee role<select name="roleName" required defaultValue=""><option value="" disabled>Select role</option>{(lookups.roles||[]).map((r:any)=><option key={r.id} value={r.name}>{r.name.replaceAll('_',' ')}</option>)}</select>{!(lookups.roles||[]).length&&<small>No employee roles are configured for this tenant.</small>}</label>:x==='serialized'?<label key={x} className="check-row"><input type="checkbox" name="serialized"/> Serialized item</label>:x==='attributesJson'?<label key={x}>Technical specifications (JSON)<textarea name={x} rows={4} placeholder='{"powerWp":550,"cellType":"N-Type TOPCon"}'/></label>:<label key={x}>{titleCase(x)}<input name={x} type={x.toLowerCase().includes('password')?'password':x.toLowerCase().includes('email')?'email':['price','purchasePrice','discountPercent','taxPercent','warrantyYears','reorderLevel','capacityKw','basePrice','monthlyBill','requiredCapacityKw'].includes(x)?'number':'text'} step={['price','purchasePrice','discountPercent','taxPercent','reorderLevel','capacityKw','basePrice','monthlyBill','requiredCapacityKw'].includes(x)?'0.01':undefined} min={['price','purchasePrice','discountPercent','taxPercent','warrantyYears','reorderLevel','capacityKw','basePrice','monthlyBill','requiredCapacityKw'].includes(x)?'0':undefined} placeholder={titleCase(x)} minLength={x==='adminPassword'?12:undefined} required={['name','sku','code','slug','email','password','adminName','adminEmail','adminPassword','purchasePrice','price','discountPercent','taxPercent','reorderLevel'].includes(x)}/></label>)}<div className="form-actions"><button>Save {createLabel}</button><button type="button" className="secondary" onClick={()=>setCreateOpen(false)}>Cancel</button></div></form>}
 {detailRecord&&<section className="card record-detail"><div className="editor-heading"><div><p className="eyebrow">RECORD DETAILS</p><h2>{detailRecord.name||detailRecord.quotationNumber||detailRecord.orderNumber||detailRecord.email||createLabel}</h2></div><button type="button" className="secondary" onClick={()=>setDetailRecord(null)}>Close</button></div><dl>{Object.entries(detailRecord).filter(([key])=>!['id','tenantId','vendorId'].includes(key)&&!/password|token|secret|credential/i.test(key)).map(([key,value]:any)=><div key={key}><dt>{titleCase(key)}</dt><dd>{value===null||value===undefined||value===''?'—':typeof value==='object'?JSON.stringify(value):String(value)}</dd></div>)}</dl></section>} {editing&&<RecordEditor record={editing} tab={tab} lookups={lookups} s={s} send={send} done={load} cancel={()=>setEditing(null)} error={error}/>}
 {tab==='operations'&&<OperationsPanel s={s} api={api} send={send} error={error}/>}
 {tab==='finance-service'&&<FinanceServicePanel s={s} api={api} send={send} error={error}/>}
 {tab==='settings'&&<SettingsForm s={s} error={error}/>}
 {createOpen&&tab==='packages'&&<PackageForm s={s} lookups={lookups} done={load} error={error}/>}
 {createOpen&&tab==='surveys'&&<SurveyForm s={s} lookups={lookups} done={load} error={error}/>}
 {createOpen&&tab==='quotations'&&s.user.accountType==='VENDOR'&&<QuoteForm s={s} lookups={lookups} done={load} error={error}/>}
 {['operations','finance-service','settings'].includes(tab)?null:<div className="card management-list"><div className="table-toolbar"><div><h2>{labels[tab]||titleCase(tab)} list</h2><span className="muted">{filtered.length} records</span></div><div className="table-controls"><input aria-label={'Search '+createLabel+' records'} placeholder={'Search '+createLabel.toLowerCase()+' records…'} value={search} onChange={e=>{setSearch(e.target.value);setPage(0)}}/>{hasStatus&&<select aria-label="Filter by status" value={statusFilter} onChange={e=>{setStatusFilter(e.target.value);setPage(0)}}><option value="ALL">All statuses</option><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option><option value="SUSPENDED">Suspended</option><option value="PENDING">Pending</option><option value="DRAFT">Draft</option><option value="SENT">Sent</option><option value="ACCEPTED">Accepted</option><option value="REJECTED">Rejected</option></select>}</div></div>{loading?<div className="table-state">Loading {createLabel.toLowerCase()} records…</div>:!filtered.length?<div className="table-state"><h3>{search||statusFilter!=='ALL'?'No matching records':'No records yet'}</h3><p>{search||statusFilter!=='ALL'?'Adjust your search or status filter.':'Records will appear here when they are created.'}</p></div>:<><div className="table-wrap management-table-wrap"><table className="management-table"><thead><tr>{(cols.length?cols:Object.keys(pageRows[0]).filter(k=>!['id','tenantId','vendorId'].includes(k)).slice(0,6).map(k=>[k,titleCase(k)])).map(([key,label]:any)=><th key={key} aria-sort={sortKey===key?(sortDir==='asc'?'ascending':'descending'):'none'}><button type="button" className="sort-button" onClick={()=>sort(key)}>{label}<span>{sortKey===key?(sortDir==='asc'?'↑':'↓'):'↕'}</span></button></th>)}<th className="actions-heading">Actions</th></tr></thead><tbody>{pageRows.map((x:any)=><tr key={x.id}>{(cols.length?cols:Object.keys(pageRows[0]).filter(k=>!['id','tenantId','vendorId'].includes(k)).slice(0,6).map(k=>[k,titleCase(k)])).map(([key]:any)=><td key={key} data-label={titleCase(key)}>{formatCell(x,key)}</td>)}<td className="table-actions" data-label="Actions">{renderActions(x)}</td></tr>)}</tbody></table></div><div className="table-pagination"><span>Showing {page*pageSize+1}–{Math.min((page+1)*pageSize,filtered.length)} of {filtered.length}</span><div className="actions"><button type="button" className="secondary" disabled={page===0} onClick={()=>setPage(v=>v-1)}>Previous</button><span>Page {page+1} of {Math.max(1,Math.ceil(filtered.length/pageSize))}</span><button type="button" className="secondary" disabled={(page+1)*pageSize>=filtered.length} onClick={()=>setPage(v=>v+1)}>Next</button></div></div></>}</div>}
 </section>;
}
function PackageForm({s,lookups,done,error}:any){
 const[items,setItems]=useState<any[]>([]);
 const[productId,setProductId]=useState('');
 const[quantity,setQuantity]=useState(1);
 const[optionalItem,setOptionalItem]=useState(false);
 const[imageFile,setImageFile]=useState<File|null>(null);
 const[busy,setBusy]=useState(false);
 const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;if(items.length===0){error('Add at least one package component');return}const x:any=Object.fromEntries(new FormData(form));['capacityKw','basePrice','warrantyYears'].forEach(k=>{if(x[k]!=='')x[k]=Number(x[k])});x.items=items;setBusy(true);try{const created=await send('/packages',x,s);if(imageFile)await uploadApi('/packages/'+created.id+'/image',imageFile,s);form.reset();setItems([]);setImageFile(null);await done();error('Solar package saved.')}catch(z:any){error(z.message)}finally{setBusy(false)}};
 const addItem=()=>{if(!productId||quantity<1){error('Select a product and positive quantity');return}setItems(v=>[...v,{productId,quantity,optionalItem}]);setProductId('');setQuantity(1);setOptionalItem(false)};
 return <form className="card form" onSubmit={submit}><h2>Create Configurable Solar Package</h2><input name="code" placeholder="Package code" required/><input name="name" placeholder="Package name" required/><input name="capacityKw" type="number" step="0.01" placeholder="Capacity kW" required/><input name="packageType" placeholder="Package type" required/><input name="basePrice" type="number" step="0.01" placeholder="Base price" required/><input name="warrantyYears" type="number" min="0" placeholder="Warranty years"/><label>Package image (JPEG, PNG or WebP, max 5 MB)<input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>setImageFile(e.target.files?.[0]||null)}/></label><h3>Package components</h3><select value={productId} onChange={e=>setProductId(e.target.value)}><option value="">Select product</option>{(lookups.products||[]).filter((p:any)=>p.active).map((p:any)=><option key={p.id} value={p.id}>{p.name} · {p.sku}</option>)}</select>{!(lookups.products||[]).filter((p:any)=>p.active).length&&<p className="muted">Add an active product under a category before configuring package components.</p>}<input type="number" min="1" value={quantity} onChange={e=>setQuantity(Number(e.target.value))} placeholder="Quantity"/><label><input type="checkbox" checked={optionalItem} onChange={e=>setOptionalItem(e.target.checked)}/> Optional component</label><button type="button" onClick={addItem}>Add component</button>{items.map((item:any,i:number)=><article key={i}><span>{(lookups.products||[]).find((p:any)=>p.id===item.productId)?.name||item.productId} × {item.quantity}</span><button type="button" onClick={()=>setItems(v=>v.filter((_,j)=>j!==i))}>Remove</button></article>)}<button disabled={busy}>{busy?'Saving package…':'Create package'}</button></form>
}
function SurveyForm({s,lookups,done,error}:any){const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const f:any=Object.fromEntries(new FormData(form));['usableAreaSqft','sanctionedLoadKw','monthlyElectricityBill','latitude','longitude'].forEach(k=>f[k]=f[k]?Number(f[k]):null);if(f.scheduledAt)f.scheduledAt=new Date(f.scheduledAt).toISOString();try{await send('/surveys',f,s);form.reset();await done()}catch(z:any){error(z.message)}};return <form className="card form" onSubmit={submit}><h2>Create Site Survey</h2><select name="leadId" required defaultValue=""><option value="" disabled>Select a lead</option>{(lookups.leads||[]).map((x:any)=><option key={x.id} value={x.id}>{x.enquiryId||x.id} · {x.stage}</option>)}</select>{!(lookups.leads||[]).length&&<p className="muted">No leads yet. Create an enquiry, then choose “Convert to Lead” in the Enquiries list before scheduling a survey.</p>}<input name="scheduledAt" type="datetime-local" required/><select name="assignedUserId" defaultValue={s.user.id}><option value={s.user.id}>Assign to me</option>{(lookups.users||[]).filter((u:any)=>u.id!==s.user.id).map((u:any)=><option key={u.id} value={u.id}>{u.name}</option>)}</select><input name="propertyType" placeholder="Property type"/><input name="roofType" placeholder="Roof type"/><input name="usableAreaSqft" placeholder="Usable area sqft"/><input name="shading" placeholder="Shading"/><input name="sanctionedLoadKw" placeholder="Sanctioned load kW"/><input name="roofOrientation" placeholder="Roof orientation"/><input name="latitude" type="number" step="0.0000001" placeholder="GPS latitude"/><input name="longitude" type="number" step="0.0000001" placeholder="GPS longitude"/><input name="monthlyElectricityBill" type="number" min="0" step="0.01" placeholder="Monthly electricity bill"/><input name="electricalPhase" placeholder="Electrical phase"/><input name="meterType" placeholder="Meter type"/><textarea name="notes" placeholder="Notes"/><select name="status"><option>SCHEDULED</option><option>COMPLETED</option></select><button>Save Survey</button></form>}
function QuoteForm({s,lookups,done,error}:any){
 const [kind,setKind]=useState('product');
 const [catalogId,setCatalogId]=useState('');
 const [quantity,setQuantity]=useState(1);
 const [lines,setLines]=useState<any[]>([]);
 const [leadId,setLeadId]=useState('');
 const [customerId,setCustomerId]=useState('');
 const options=kind==='product'?(lookups.products||[]):(lookups.packages||[]);
 const selectedLead=(lookups.leads||[]).find((x:any)=>x.id===leadId);
 const surveyOptions=(lookups.surveys||[]).filter((x:any)=>leadId&&x.leadId===leadId);
 const addLine=()=>{
  if(!catalogId||quantity<1){error('Choose an active product/package and a positive quantity');return}
  if(lines.some(x=>x.kind===kind&&x.id===catalogId)){error('This item is already in the quotation');return}
  setLines(v=>[...v,{kind,id:catalogId,quantity}]);setCatalogId('');setQuantity(1);
 };
 const submit=async(e:React.FormEvent<HTMLFormElement>)=>{
  e.preventDefault();const form=e.currentTarget;const f:any=Object.fromEntries(new FormData(form));
  if(!lines.length){error('Add at least one product or package to the quotation');return}
  const items=lines.map(line=>line.kind==='product'?{productId:line.id,packageId:null,quantity:line.quantity}:{productId:null,packageId:line.id,quantity:line.quantity});
  const payload={customerId:f.customerId,leadId:f.leadId||null,surveyId:f.surveyId||null,discountPercent:Number(f.discountPercent||0),validUntil:f.validUntil,items};
  try{await send('/quotations',payload,s);form.reset();setLines([]);setCustomerId('');setLeadId('');await done()}catch(z:any){error(z.message)}
 };
 const label=(line:any)=>{const list=line.kind==='product'?(lookups.products||[]):(lookups.packages||[]);const item=list.find((x:any)=>x.id===line.id);return item?.name||line.id};
 return <form className="card form" onSubmit={submit}>
  <h2>Create Quotation</h2>
  <label>Customer<select name="customerId" required value={customerId} onChange={e=>{setCustomerId(e.target.value);setLeadId('')}}><option value="" disabled>Select customer</option>{(lookups.customers||[]).map((x:any)=><option key={x.id} value={x.id}>{x.name} · {x.email}</option>)}</select></label>
  {!(lookups.customers||[]).length&&<p className="muted">No customers found. Create a customer or ask them to register for this vendor store.</p>}
  <label>Lead (optional)<select name="leadId" value={leadId} onChange={e=>setLeadId(e.target.value)}><option value="">No lead</option>{(lookups.leads||[]).filter((x:any)=>x.customerId===customerId).map((x:any)=><option key={x.id} value={x.id}>{x.id} · {x.stage}</option>)}</select></label>
  <label>Site survey (optional)<select name="surveyId" defaultValue=""><option value="">No survey</option>{surveyOptions.map((x:any)=><option key={x.id} value={x.id}>{x.id} · {x.status}</option>)}</select></label>
  {leadId&&!selectedLead?.customerId&&<p className="muted">This lead is not linked to a customer yet. Convert enquiries after adding a valid customer email, then refresh this form.</p>}
  <h3>Quotation items</h3>
  <select value={kind} onChange={e=>{setKind(e.target.value);setCatalogId('')}}><option value="product">Product</option><option value="package">Solar package</option></select>
  <select value={catalogId} onChange={e=>setCatalogId(e.target.value)}><option value="">Select {kind}</option>{options.filter((x:any)=>x.active).map((x:any)=><option key={x.id} value={x.id}>{x.name} · ₹{kind==='product'?x.price:x.basePrice}</option>)}</select>
  {!options.filter((x:any)=>x.active).length&&<p className="muted">No active {kind}s. Add products under a category or configure a solar package first.</p>}
  <input type="number" min="1" step="1" value={quantity} onChange={e=>setQuantity(Number(e.target.value))} aria-label="Quantity"/>
  <button type="button" onClick={addLine}>Add quotation item</button>
  {lines.map((line:any,i:number)=><article key={line.kind+line.id}><span>{label(line)} × {line.quantity}</span><button type="button" onClick={()=>setLines(v=>v.filter((_,j)=>i!==j))}>Remove</button></article>)}
  <input name="discountPercent" type="number" min="0" max="100" step="0.01" defaultValue="0" placeholder="Discount %"/>
  <input name="validUntil" type="date" required/>
  <button>Create Quote</button>
 </form>
}
async function downloadPdf(q:any,s:Session,error:any){try{const r=await fetch(API_BASE+`/api/v1/quotations/${q.id}/pdf`,{headers:{Authorization:`Bearer ${s.accessToken}`}});if(!r.ok)throw Error('PDF download failed');const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download=`${q.quotationNumber}.pdf`;a.click();URL.revokeObjectURL(u)}catch(e:any){error(e.message)}}
createRoot(document.getElementById('root')!).render(<App/>);
